{"actions":[{"type":"success_contract","objective":"Start /app/alpine.iso in QEMU in the background and expose a login prompt reachable via telnet 127.0.0.1 6665, then block until readiness is confirmed.","required_artifacts":["A running QEMU process launched from /app/alpine.iso","A launch receipt/log showing the VM started with host port 6665 forwarded to guest port 23"],"required_behaviors":["QEMU remains running in the background after launch","Connecting to 127.0.0.1:6665 reaches the guest login prompt","The prompt is observed before finalization"],"known_invalid_patterns":["Only verifying file existence or that QEMU was invoked","Port 6665 open without a login prompt","VM exits before the prompt is observed","Foreground launch that does not leave the VM running"],"verification_plan":["Inspect workspace and any prior receipts for launch details","Launch QEMU detached/backgrounded with telnet forwarding to host port 6665","Probe 127.0.0.1:6665 until the login prompt is observed","Keep the VM running after successful probe"],"finalization_evidence_required":["Receipt-backed launch command/output","Receipt-backed probe output showing the login prompt on 127.0.0.1:6665"],"notes":["Use existing visible Alpine ISO asset at /app/alpine.iso unless evidence suggests a different boot path is required."]},{"type":"working_checklist","items":["Inspect visible files and any prior receipts for QEMU-related evidence","Determine whether qemu-system-x86_64 or an equivalent binary is available","Launch the Alpine ISO with user networking and hostfwd tcp::6665-:23","Probe localhost:6665 for the login prompt and retain the running VM"],"model_notes":{"args":{"current_focus":"Inspect workspace contents and determine the correct QEMU invocation","evidence_gaps":["Need to inspect visible files and any existing receipts before launching"],"evidence_required_before_finalization":["Launch receipt","Probe receipt showing login prompt"],"implementation_approach":["Look for existing disk/ISO assets and any helper launch scripts","Use QEMU user networking with hostfwd to guest telnet port 23 on host port 6665","Run QEMU detached/backgrounded and capture logs","Probe localhost:6665 until the login prompt is observed"],"known_bad_behavior":["QEMU not running in background","Port forwarded incorrectly","Port open but no login prompt","VM exits before verification"],"next_steps":["Inspect workspace files","Determine available QEMU binary and launch options","Start VM and probe telnet endpoint"],"objective":"Bring up Alpine ISO in QEMU and expose login prompt on localhost:6665","risks":["QEMU may not be installed or may require a specific machine/acceleration setting","The ISO may need a bootable disk or different serial console settings"],"validation_strategy":["Use a telnet or netcat probe against 127.0.0.1:6665","Confirm the prompt text matches Alpine login prompt behavior","Keep the VM running after successful probe"],"verification_test_strategy":["Initial port probe after launch","Prompt-content probe after connection"]}}},{"type":"plan_update","current_focus":"Inspect workspace contents and determine the correct QEMU invocation","notes":["Proceed to evidence gathering before any repeated launch attempts."]}]}
